const result = await std.process.exec("git", ["status", "--short"]);
if (result.stdout.trim() !== "") {
  std.warn("working tree is dirty");
}
await std.dekit.start("+workers");

await std.dekit.add("tmp/build", ["npm", "run", "build"]);
const started = await std.dekit.start("+workers");
std.log(`started ${started} workers`);

await std.dekit.start("db");
await std.dekit.wait("db");
await std.process.exec("./seed.sh");

await std.fs.mkdir("out", { recursive: true });
await std.fs.write("out/hello.txt", "hello\n");
std.log(await std.fs.read("out/hello.txt"));

const { stdout, code } = await std.process.exec("git", ["rev-parse", "HEAD"]);
if (code !== 0) std.process.exit(1);
std.log(stdout.trim());
